/* Stable coordinate scales shared by the live labs. */
(function(root){
 let expanded=null,expandedRedraw=null;
 if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('keydown',e=>{if(!expanded)return;if(e.key==='Escape'){const id=expanded;expanded=null;expandedRedraw?.();document.getElementById(id+'ScaleControls')?.children[4]?.focus?.();}if(e.key==='Tab'){const buttons=[...document.getElementById(expanded+'ScaleControls').querySelectorAll('button')],index=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(index+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();}});
 const states=new Map(),nice=n=>{const power=10**Math.floor(Math.log10(Math.max(n,1e-12))),v=n/power;return (v<=1?1:v<=2?2:v<=5?5:10)*power;},label=n=>Number(n.toPrecision(4)).toString();
 function frame(id,view,fit,redraw,unit){
  const key=id+':'+view+':'+unit;let state=states.get(key);if(!state){state={...fit,zoom:1,auto:false};states.set(key,state);}if(state.auto)Object.assign(state,fit,{zoom:1});
  const result={...state,scale:state.scale*state.zoom,extent:state.extent/state.zoom};
  if(typeof document!=='undefined'){const svg=document.getElementById(id);if(svg?.parentElement&&document.createElement){let bar=document.getElementById(id+'ScaleControls');if(!bar){bar=document.createElement('div');bar.id=id+'ScaleControls';bar.className='graph-controls';svg.insertAdjacentElement('afterend',bar);}bar.innerHTML='';
   for(const [text,action] of [['Zoom in',()=>state.zoom=Math.min(64,state.zoom*1.5)],['Zoom out',()=>state.zoom=Math.max(1/64,state.zoom/1.5)],['Fit to data',()=>Object.assign(state,fit,{zoom:1})],[state.auto?'Lock scale':'Enable auto-fit',()=>state.auto=!state.auto]]){const button=document.createElement('button');button.type='button';button.textContent=text;button.onclick=()=>{action();redraw();};bar.appendChild(button);}
   const expand=document.createElement('button');expand.type='button';expand.textContent=expanded===id?'Close expanded view':'Expand graph';expand.onclick=()=>{expanded=expanded===id?null:id;expandedRedraw=redraw;redraw();document.getElementById(id+'ScaleControls')?.children[4]?.focus?.();};bar.appendChild(expand);svg.classList?.toggle('graph-expanded',expanded===id);bar.classList?.toggle('graph-expanded-controls',expanded===id);document.body?.classList?.toggle('graph-is-expanded',expanded!==null);
   const note=document.createElement('p');note.className='diagram-help';note.textContent=(state.auto?'Auto-fit: scale changes with inputs.':'Scale locked: input changes preserve arrow size comparisons.')+' Axis labels in '+unit+'. '+(view==='iso'?'3D axes are projected; screen lengths and angles are foreshortened.':'Equal scale on both axes.')+' Use Fit to data if a point leaves the frame.'+(expanded===id?' Press Escape or Close expanded view to return.':'');bar.appendChild(note);
  }}return result;
 }
 function axisRange(origin,direction,height=400){let low=-Infinity,high=Infinity;for(const [o,d,min,max] of [[origin[0],direction[0],12,588],[origin[1],direction[1],42,height-18]]){if(Math.abs(d)<1e-12)continue;const a=(min-o)/d,b=(max-o)/d;low=Math.max(low,Math.min(a,b));high=Math.min(high,Math.max(a,b));}return [low,high];}
 function axesSVG(view,screen,extent,unit,height=400){const names=['x','y','z'],pair={xy:[0,1],xz:[0,2],yz:[1,2]}[view],origin=screen([0,0,0]);let out='',steps=[];
  for(let i=0;i<3;i++){if(pair&&!pair.includes(i))continue;const point=n=>names.map((_,j)=>j===i?n:0),one=screen(point(1)),direction=one.map((v,j)=>v-origin[j]);if(Math.hypot(...direction)<1e-12)continue;const [low,high]=axisRange(origin,direction,height),step=nice(65/Math.hypot(...direction));steps.push(names[i]+': '+label(step));const a=screen(point(low)),b=screen(point(high));out+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#718297" stroke-width="1.2"/><text class="axis-name" x="${Math.max(16,Math.min(550,b[0]-18))}" y="${Math.max(55,Math.min(height-24,b[1]-10))}" fill="#cfdae8" font-size="16">+${names[i]}</text>`;
   for(let n=Math.ceil(low/step);n<=Math.floor(high/step);n++){if(!n)continue;const p=screen(point(n*step));if(Math.hypot(p[0]-b[0],p[1]-b[1])<48||Math.hypot(p[0]-a[0],p[1]-a[1])<25)continue;out+=`<circle cx="${p[0]}" cy="${p[1]}" r="2.5" fill="#a9b8ca"/><text class="axis-tick" x="${p[0]+(i===2?10:7)}" y="${p[1]+(i===2?5:20)}" fill="#b8c7d9" font-size="13">${view==='iso'?names[i]+'=':''}${label(n*step)}</text>`;}}
  return out+`<text class="axis-caption" x="12" y="23" fill="#cfdae8" font-size="14">Axis coordinates (${unit}) · tick steps ${steps.join(' / ')} ${unit}</text>`;
 }
 // Place labels in SVG coordinates so enlargement preserves the same spacing.
 function layout(svg){if(!svg?.querySelectorAll||!svg.viewBox?.baseVal)return;const height=svg.viewBox.baseVal.height,boxes=[],texts=[...svg.querySelectorAll('text')].sort((a,b)=>Number(a.classList.contains('axis-tick'))-Number(b.classList.contains('axis-tick')));
  for(const text of texts){if(!text.getBBox)continue;const original=text.getBBox();if(!original.width)continue;let placed=false;for(const [dx,dy] of [[0,0],[0,-22],[0,22],[25,0],[-45,0],[25,-22],[-45,22],[0,-44],[0,44]]){const x=Math.max(8,Math.min(592-original.width,original.x+dx)),y=Math.max(5,Math.min(height-8-original.height,original.y+dy)),box={x,y,width:original.width,height:original.height};if(boxes.some(b=>box.x<b.x+b.width+5&&box.x+box.width+5>b.x&&box.y<b.y+b.height+4&&box.y+box.height+4>b.y))continue;text.setAttribute('transform',`translate(${x-original.x} ${y-original.y})`);boxes.push(box);placed=true;break;}if(!placed){text.setAttribute('visibility','hidden');}}
 }
 const animations=new WeakMap();
 function paint(svg,html){
  if(!svg)return;const animated=typeof requestAnimationFrame==='function'&&typeof cancelAnimationFrame==='function'&&svg.querySelectorAll&&!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  if(animations.has(svg)){cancelAnimationFrame(animations.get(svg));animations.delete(svg);}if(!animated){svg.innerHTML=html;layout(svg);return;}
  const collect=()=>{const counts={},map=new Map();for(const node of svg.querySelectorAll('line,path,circle,text')){if(node.closest('defs')||node.tagName==='circle'&&Number(node.getAttribute('r'))<=2.5)continue;const tag=node.tagName,base=tag==='text'?tag+':'+node.textContent:tag==='circle'?tag+':'+(node.dataset.point||node.dataset.force||''):tag,index=counts[base]||0;counts[base]=index+1;map.set(base+':'+index,node);}return map;},previous=collect();svg.innerHTML=html;const changes=[],numberPattern=/-?\d*\.?\d+(?:e[-+]?\d+)?/gi;
  for(const [key,node] of collect()){const old=previous.get(key);if(!old){node.animate?.([{opacity:0},{opacity:1}],{duration:220});continue;}for(const attr of ['x','y','x1','x2','y1','y2','cx','cy']){const a=old.getAttribute(attr),b=node.getAttribute(attr);if(a===null||b===null||!Number.isFinite(Number(a))||!Number.isFinite(Number(b))||a===b)continue;changes.push({node,attr,a:Number(a),b:Number(b)});node.setAttribute(attr,a);}const a=old.getAttribute('d'),b=node.getAttribute('d');if(a&&b&&a!==b&&a.replace(numberPattern,'#')===b.replace(numberPattern,'#')){changes.push({node,attr:'d',a:a.match(numberPattern).map(Number),b:b.match(numberPattern).map(Number),target:b});node.setAttribute('d',a);}}
  let started=null;const advance=time=>{started??=time;const t=Math.min(1,(time-started)/220),ease=1-(1-t)**3;for(const c of changes){if(c.attr==='d'){let i=0;c.node.setAttribute('d',c.target.replace(numberPattern,()=>{const value=c.a[i]+(c.b[i]-c.a[i])*ease;i++;return value;}));}else c.node.setAttribute(c.attr,c.a+(c.b-c.a)*ease);}if(t<1)animations.set(svg,requestAnimationFrame(advance));else{animations.delete(svg);layout(svg);}};animations.set(svg,requestAnimationFrame(advance));
 }
 const api={frame,axesSVG,axisRange,layout,paint,nice};if(typeof module!=='undefined')module.exports=api;else root.GraphScales=globalThis.GraphScales=api;
})(typeof window!=='undefined'?window:globalThis);
